int set_binprm_credentials(struct linux_binprm *bprm) {
    int ret;

    const struct cred *old_creds = current_cred();
    struct cred *new_creds;

    new_creds = prepare_creds();
    if (!new_creds)
        return -ENOMEM;

    ret = security_bprm_set_creds(bprm);
    if (ret)
        goto error;

    if (bprm->cred_prepared) {
        ret = -EACCES;
        goto error;
    }

    if (bprm->file) {
        mode_t mode;
        struct inode *inode = file_inode(bprm->file);
        mode = inode->i_mode;

        if (S_ISUID & mode) {
            new_creds->uid = inode->i_uid;
            new_creds->euid = inode->i_uid;
        }
        if (S_ISGID & mode) {
            new_creds->gid = inode->i_gid;
            new_creds->egid = inode->i_gid;
        }
    }

    if (new_creds->euid != new_creds->uid ||
        new_creds->egid != new_creds->gid)
        new_creds->securebits |= SECURE_KEEP_CAPS;

    if (task_no_new_privs(current))
        new_creds->securebits &= ~SECURE_KEEP_CAPS;

    if (new_creds->euid != old_creds->euid ||
        new_creds->egid != old_creds->egid ||
        new_creds->uid != old_creds->uid ||
        new_creds->gid != old_creds->gid)
        audit_log_sid(new_creds);

    ret = security_bprm_compute_perm(bprm, new_creds);
    if (ret)
        goto error;

    commit_creds(new_creds);
    return 0;

error:
    put_cred(new_creds);
    return ret;
}

int set_binprm_credentials(struct linux_binprm *bprm) {
    struct cred *new, *old;
    int ret;

    old = current_cred();
    new = prepare_creds();
    if (!new)
        return -ENOMEM;

    if (bprm->file) {
        struct inode *inode = file_inode(bprm->file);
        struct dentry *dentry = bprm->file->f_path.dentry;

        if (S_ISUID & inode->i_mode) {
            if (!uid_eq(old->uid, INVALID_UID)) {
                new->euid = inode->i_uid;
                if (!uid_eq(new->euid, old->euid))
                    new->fsuid = new->euid;
            }

            if (cap_valid(current_cred()->cap)) {
                new->cap = cap_intersect(current_cred()->cap, bprm->cap_effective);
                cap_set_flag(new->cap, CAP_EFFECTIVE, cap_capable(new->cap, CAP_EFFECTIVE), NULL);
            }
        }

        if (S_ISGID & inode->i_mode) {
            if (!gid_eq(old->gid, INVALID_GID)) {
                new->egid = inode->i_gid;
                if (!gid_eq(new->egid, old->egid))
                    new->fsgid = new->egid;
            }
        }

        if (cap_valid(bprm->cap_effective) && (bprm->cap_effective->val || bprm->cap_permitted->val)) {
            new->cap = cap_combine(new->cap, bprm->cap_effective);
        }
    }

    ret = security_bprm_set_creds(bprm);
    if (ret < 0) {
        abort_creds(new);
        return ret;
    }

    if (task_frozen(current))
        new->no_new_privs = 1;

    if (new->securebits & SECURE_KEEP_CAPS)
        new->cap = cap_combine(new->cap, current_cred()->cap);

    if (new->cap->val)
        set_bit(__cap_to_bit(CAP_SETPCAP), &new->cap->inheritable);

    if (new->euid != old->euid || new->egid != old->egid || new->fsuid != old->fsuid || new->fsgid != old->fsgid ||
        new->cap->val != current_cred()->cap->val) {
        audit_log_capset(new->cap, current_cred()->cap);
    }

    commit_creds(new);
    return 0;
}

int set_binprm_credentials(struct linux_binprm *bprm) {
    int ret = 0;

    // Retrieve current credentials
    const struct cred *old_cred = current_cred();
    struct cred *new_cred = prepare_creds();

    if (!new_cred)
        return -ENOMEM;

    // Check and handle file capabilities
    if (bprm->file) {
        struct inode *inode = file_inode(bprm->file);
        mode_t mode = inode->i_mode;

        if (S_ISUID & mode) {
            // Handle setuid binary
            if (S_ISGID & mode)
                new_cred->fsuid = inode->i_uid;
            else
                new_cred->fsuid = old_cred->uid;

            // Root privilege management
            if (uid_eq(new_cred->fsuid, GLOBAL_ROOT_UID)) {
                if (!ns_capable(inode->i_sb->s_user_ns, CAP_SETUID)) {
                    ret = -EPERM;
                    goto error;
                }
            }
        }
    }

    // Modify new credentials based on current capabilities
    new_cred->euid = new_cred->fsuid;
    new_cred->egid = new_cred->fsgid;

    // Clear dangerous flags
    new_cred->cap_effective &= ~CAP_TO_MASK(CAP_KILL);
    new_cred->cap_permitted &= ~CAP_TO_MASK(CAP_KILL);

    // Enforce tracing permissions
    if (!ptracer_capable(current, new_cred)) {
        ret = -EPERM;
        goto error;
    }

    // Audit logging based on effective capabilities
    if (new_cred->cap_effective) {
        audit_log_capset(new_cred);
    }

    // Update secure bits
    ret = set_secbits(new_cred, bprm->file, old_cred);
    if (ret < 0)
        goto error;

    // Commit new credentials
    ret = commit_creds(new_cred);
    if (ret < 0)
        return ret;

    return 0;

error:
    abort_creds(new_cred);
    return ret;
}

#include <linux/binprm.h>
#include <linux/cred.h>
#include <linux/capability.h>
#include <linux/audit.h>
#include <linux/generic_ping.h>

int set_binprm_credentials(struct linux_binprm *bprm) {
    struct cred *new;
    struct cred *old;

    old = current_cred();
    new = prepare_creds();
    if (!new)
        return -ENOMEM;

    /* Handle setuid binary with root privilege */
    if (bprm->cred->uid != old->uid || bprm->cred->euid != old->euid) {
        if (cap_setino(bprm->file, &new->cap_effective, CAP_INHERITABLE, CAP_PERMITTED))
            return -EPERM;

        if (new->cap_effective & CAP_EFFECTIVE) {
            if (task_setcap(current, new) < 0)
                return -EPERM;
        } else {
            new->cap_permitted = new->cap_effective = 0;
        }
    }

    /* Clear dangerous capability flags */
    if (bprm->secureexec) {
        new->cap_effective &= ~CAP_EFFECTIVE;
        new->cap_permitted &= ~CAP_EFFECTIVE;
    }

    /* Enforce ptrace permissions if tracing is active */
    if (ptrace_parent(current)) {
        if (new->uid != old->uid || new->euid != old->euid)
            return -EPERM;
    }

    /* Audit the effective capabilities if non-zero */
    if (new->cap_effective || new->cap_permitted) {
        audit_log_cap(bprm->file, new);
    }

    /* Update secure bits */
    bprm->secureexec = 1;
    current->securebits = bprm->securebits;

    commit_creds(new);
    return 0;
}
